const fs = require("fs");
const path = require("path");
const root = "/w/node_modules/agents";
let pkg, text;
try {
  pkg = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"));
  text = fs.readFileSync(path.join(root, pkg.exports["./chat"].types), "utf8");
} catch (e) {
  console.error("ERROR: cannot read agents/chat types: " + e.message);
  process.exit(2);
}
const m = text.match(/\/\*\*((?:(?!\*\/)[\s\S])*)\*\/\s*declare function resolveToolMergeId\(/);
if (!m || !/declare function reconcileMessages\(/.test(text)) {
  console.error("ERROR: resolveToolMergeId or reconcileMessages declaration not found in agents " + pkg.version);
  process.exit(2);
}
const doc = m[1];
if (/@deprecated[\s\S]*reconcileMessages/.test(doc)) {
  console.log("OK: agents " + pkg.version + " marks resolveToolMergeId @deprecated in favour of reconcileMessages");
  process.exit(0);
}
if (!/@deprecated/.test(doc)) {
  console.error("FAIL: resolveToolMergeId is not marked @deprecated");
  process.exit(1);
}
console.error("ERROR: unexpected resolveToolMergeId doc: " + doc);
process.exit(2);

